			}
			add_modifier = {
				name = heroes_of_the_people
				days = long_modifier_time
				multiplier = scope:ig.var:promise_quest_degree
			}
		}
		promise_quest = yes
		add_journal_entry = { #must do this last
			type = je_negotiate_sol
		}
